import React from 'react';
import { IExpenseType } from '../../core/Interface/expense.interface';
import { ColumnDef } from '@tanstack/react-table';
import { Box, Tooltip, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { useTranslation } from 'react-i18next';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';

const ActionBtn = ({
  onClick, title, color, children,
}: {
  onClick: () => void; title: string; color: string; children: React.ReactNode;
}) => (
  <Tooltip arrow title={title}>
    <Box
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      sx={{
        alignItems: 'center',
        background: alpha(color, 0.1),
        border: `1px solid ${alpha(color, 0.22)}`,
        borderRadius: '7px',
        color,
        cursor: 'pointer',
        display: 'flex',
        height: 30,
        justifyContent: 'center',
        transition: 'all 0.15s',
        width: 30,
        '&:hover': { background: color, color: '#fff', transform: 'scale(1.07)' },
      }}
    >
      {children}
    </Box>
  </Tooltip>
);

const useExpenseTypeColumn = (
  handleEditExpense: (data: IExpenseType) => void,
  handleConfirmDelete: (data: IExpenseType) => void
) => {
  const { t } = useTranslation(['expenseType']);

  return [
    {
      accessorKey: 'sn',
      header: '#',
      size: 52,
      cell: (cell) => (
        <Typography sx={{ color: alpha('#0F1D4D', 0.45), fontSize: 13, fontWeight: 600 }}>
          {cell.row.index + 1}
        </Typography>
      ),
    },
    {
      accessorKey: 'name',
      header: t('expenseType:title.name'),
      size: 200,
      cell: (cell) => (
        <Typography sx={{ color: '#0F1D4D', fontSize: 13, fontWeight: 600 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'code',
      header: t('expenseType:title.code'),
      size: 160,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'description',
      header: t('expenseType:title.description'),
      size: 260,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      id: 'actions',
      header: '',
      size: 80,
      cell: (cell) => (
        <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75, justifyContent: 'flex-end' }}>
          <ActionBtn color="#D97706" onClick={() => handleEditExpense(cell.row.original)} title="Edit Expense Type">
            <EditIcon sx={{ fontSize: 15 }} />
          </ActionBtn>
          <ActionBtn color="#DC2626" onClick={() => handleConfirmDelete(cell.row.original)} title="Delete Expense Type">
            <DeleteIcon sx={{ fontSize: 15 }} />
          </ActionBtn>
        </Box>
      ),
    },
  ] as ColumnDef<IExpenseType>[];
};

export default useExpenseTypeColumn;
