import React, { useMemo } from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  Grid,
  TextField,
  useMediaQuery,
} from '@mui/material';
import FieldHeader from '../../../components/FieldHeader';
import { useFormik } from 'formik';
import { theme } from '../../../theme';
import { useNewExpenseTypeMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { appColors } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import { IExpenseType } from '../../../core/Interface/expense.interface';

interface INewExpenseType {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: IExpenseType;
}
const NewExpenseType = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
}: INewExpenseType) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newExpenseType, { isLoading }] = useNewExpenseTypeMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'expenseType']);
  const buttonText = data ? t('common:update') : t('common:create');

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      id: data?.id,
      name: data?.name,
      code: data?.code,
      description: data?.description,
    },
    onSubmit: async (values) => {
      try {
        const temData = {
          id: values?.id,
          name: values?.name,
          code: values?.code,
          description: values?.description,
        };
        if (!data) {
          delete values.id;
        }

        const addExpenseTypeResponse = await newExpenseType(temData).unwrap();
        if (!addExpenseTypeResponse.status) {
          showErrorMessage(addExpenseTypeResponse.message);
        } else {
          showMessage(addExpenseTypeResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(() => {
    return formik.values.name === '' ||
      formik.values.name === undefined ||
      formik.values.code === '' ||
      formik.values.code === undefined ||
      formik.values.description === '' ||
      formik.values.description === undefined
      ? false
      : true;
  }, [formik]);

  return (
    <div>
      <form onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={open}
        >
          <DialogTitle
            sx={{
              fontWeight: 600,
              p: 3,
              backgroundColor: appColors.blueGreyishLight[30],
              borderRadius: '5px',
            }}
          >
            {title}
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', p: 4, marginTop: '20px' }}
          >
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader title={t('expenseType:title.name')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('expenseType:title.name')}
                    size="small"
                    {...formik.getFieldProps('name')}
                    sx={{ height: `${theme.spacing(8)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem>
                  <FieldHeader title={t('expenseType:title.code')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('expenseType:title.code')}
                    size="small"
                    {...formik.getFieldProps('code')}
                    sx={{ height: `${theme.spacing(8)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem>
                  <FieldHeader title={t('expenseType:title.description')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('expenseType:title.description')}
                    size="small"
                    {...formik.getFieldProps('description')}
                    sx={{ height: `${theme.spacing(8)}`, width: '100%' }}
                  />
                </GridItem>
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ paddingRight: '24px', p: 4, py: 3, gap: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid || isLoading}
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
              }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewExpenseType);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
