import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import React, { CSSProperties, useMemo, useState } from 'react';
import {
  IExpenseType,
  IExpenseTypeData,
} from '../../core/Interface/expense.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllExpenseTypeQuery } from '../posApi';
import useExpenseTypeColumn from './useExpenseTypeColumn';

const useExpenseType = (
  handleEditExpense: (data: IExpenseType) => void,
  handleConfirmDelete: (data: IExpenseType) => void
) => {
  const { page } = usePageQuery();
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data: expenseTypeData,
    isLoading,
    isFetching,
    error,
  } = useGetAllExpenseTypeQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const expenseTypeDetailsMemo = useMemo(() => {
    return expenseTypeData?.data as IExpenseTypeData;
  }, [expenseTypeData?.data]);

  const filteredData = useMemo(() => {
      const text = searchText.toLowerCase().trim();
      return expenseTypeDetailsMemo?.records.filter((record) => {
        const code = record.code?.toLowerCase();
        const name = record.name?.toLowerCase();
        return name?.includes(text) || code.includes(text);
      });
    }, [expenseTypeDetailsMemo, searchText]);

  const columns = useExpenseTypeColumn(handleEditExpense, handleConfirmDelete);

  const table = useReactTable({
    data: error ? [] : filteredData,
    meta: {
      getRowStyles: (row: Row<IExpenseType>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: expenseTypeDetailsMemo?.totalRecords ?? 0,
    // pageCount: 10,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: expenseTypeDetailsMemo?.totalRecords ?? 0,
    // totalCount:  10,
    searchText,
    setSearchText,
  };
};

export default useExpenseType;
